const destination = $json.adventureDestination || 'Your Destination'; 
const travelDates = `${$json.startDate || 'N/A'} to ${$json.endDate || 'N/A'}`; 
const budget = $json.budget || 'N/A'; 
const groupSize = $json.groupSize || 'N/A'; 
const departureLocation = $json.departureLocation || 'Not specified'; 
console.log('Using departureLocation in itinerary:', departureLocation); 
let itineraryRaw = $json.itinerary || 'Itinerary details not available.'; 
console.log('Initial itineraryRaw:', itineraryRaw);
console.log('Checking for Cost Summary in itineraryRaw (case-insensitive)...');
// Normalize itineraryRaw for comparison
if (!itineraryRaw.toLowerCase().includes('cost summary:')) {
  console.log('Cost Summary missing, adding fallback');
  itineraryRaw = itineraryRaw + '\n\nCost Summary:\nFlights\t$0\nActivities\t$0\nAccommodation\t$0\nFood\t$0\n<strong>Total</strong>\t<strong>$0</strong>\n<strong>Remaining Budget</strong>\t<strong>$' + budget + '</strong>';
} else {
  console.log('Cost Summary found in itineraryRaw');
}
console.log('itineraryRaw after fallback check:', itineraryRaw);
// Preprocess itinerary to clean up Markdown and add HTML formatting
const itineraryLines = itineraryRaw.split('\n'); 
let itinerary = ''; 
let inTable = false; 
let tableRows = []; 
for (let line of itineraryLines) { 
  line = line.trim(); 
  // Skip empty lines
  if (!line) { 
    itinerary += '<br>'; 
    continue; 
  } 
  // Handle Cost Summary table
  if (line.toLowerCase().startsWith('cost summary:')) { 
    inTable = true; 
    tableRows = []; 
    itinerary += `<strong style="font-size: 16px; color: #2a4a6e; display: block; margin: 15px 0 5px 0;">${line}</strong>`; 
    continue; 
  } 
  if (inTable && (line.startsWith('Total') || line.startsWith('Remaining Budget'))) { 
    const [category, cost] = line.split('\t').map(item => item.trim()); 
    tableRows.push(`<tr><td style="border: 1px solid #e0e0e0; padding: 8px; background-color: #f0f0f0; font-weight: bold;">${category}</td><td style="border: 1px solid #e0e0e0; padding: 8px; background-color: #f0f0f0; font-weight: bold;">${cost}</td></tr>`); 
    continue; 
  } 
  if (inTable && line.includes('\t')) { 
    const [category, cost] = line.split('\t').map(item => item.trim()); 
    tableRows.push(`<tr><td style="border: 1px solid #e0e0e0; padding: 8px;">${category}</td><td style="border: 1px solid #e0e0e0; padding: 8px;">${cost}</td></tr>`); 
    continue; 
  } 
  if (inTable && !line.includes('\t')) { 
    inTable = false; 
    itinerary += `<table style="border-collapse: collapse; width: 100%; margin: 10px 0; font-size: 14px;" cellpadding="0" cellspacing="0">${tableRows.join('')}</table><br>`; 
  } 
  // Handle headings and regular lines
  if (!inTable) { 
    if (line.endsWith(':')) { 
      itinerary += `<strong style="font-size: 16px; color: #2a4a6e; display: block; margin: 15px 0 5px 0;">${line}</strong>`; 
    } else { 
      itinerary += line + '<br>'; 
    } 
  } 
} 
// Add the table if we ended in table mode
if (inTable) { 
  itinerary += `<table style="border-collapse: collapse; width: 100%; margin: 10px 0; font-size: 14px;" cellpadding="0" cellspacing="0">${tableRows.join('')}</table><br>`; 
} 
console.log('Final itinerary HTML:', itinerary);
const subject = `Your Adventure Itinerary for ${destination} - Voyage Genie`; 
const message = `<div style="font-family: 'Helvetica Neue', Arial, sans-serif; max-width: 600px; margin: 0 auto; background-color: #f7f7f7; padding: 25px; border-radius: 10px; box-shadow: 0 4px 8px rgba(0,0,0,0.1);"><div style="background-color: #2a4a6e; padding: 20px; border-radius: 10px 10px 0 0; text-align: center;"><h1 style="color: #ffffff; margin: 0; font-size: 28px;">✈️ Your Adventure Itinerary</h1></div><div style="padding: 25px; background-color: #ffffff; border-radius: 0 0 10px 10px;"><h2 style="color: #2a4a6e; font-size: 22px; margin: 0 0 15px 0;">Departing from: ${departureLocation}</h2><h2 style="color: #2a4a6e; font-size: 22px; margin: 0 0 15px 0;">Destination: ${destination}</h2><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5;"><strong>Travel Dates:</strong> ${travelDates}</p><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5;"><strong>Budget:</strong> $${budget} (for ${groupSize} travelers)</p><hr style="border: 0; border-top: 1px solid #e0e0e0; margin: 25px 0;"><h3 style="color: #2a4a6e; font-size: 18px; margin: 0 0 15px 0;">Itinerary Details</h3><div style="background-color: #f9f9f9; padding: 20px; border-radius: 6px; font-size: 14px; line-height: 1.6; color: #333333;">${itinerary}</div><hr style="border: 0; border-top: 1px solid #e0e0e0; margin: 25px 0;"><p style="color: #666666; font-size: 12px; text-align: center; margin: 0;">Generated by <strong>Voyage Genie</strong> 🌟</p></div></div>`; 
return [{ json: { resolvedEmail: $json.email || 'jtran112675@gmail.com', resolvedSubject: subject, resolvedMessage: message, itineraryHtml: message } }];

const url = 'https://exodonprofits.app.n8n.cloud/webhook/send-email';
const payload = {
  resolvedEmail: $json.resolvedEmail,
  resolvedSubject: $json.resolvedSubject,
  resolvedMessage: $json.resolvedMessage
};

try {
  const response = await $http({
    method: 'POST',
    url: url,
    body: payload,
    headers: {
      'Content-Type': 'application/json'
    }
  });

  console.log('Email trigger response:', response);
} catch (error) {
  console.error('Error triggering email workflow:', error.message);
}

return $input.all();
